<script setup>
import {computed,onBeforeUnmount,ref} from 'vue'
import {useData} from 'vitepress'
const {frontmatter}=useData(),en=computed(()=>frontmatter.value.locale==='en'),method=ref('docker'),copied=ref(false),copyError=ref(false)
let timer
const common='git clone https://github.com/rivomesh/rivomesh.git\ncd rivomesh\n'
const command=computed(()=>common+(method.value==='docker'?'export RIVOMESH_TOKEN="$(openssl rand -hex 32)"\ndocker compose -f deploy/docker-compose.yml up -d --build':'mvn -s build/settings.xml verify\nexport RIVOMESH_TOKEN="$(openssl rand -hex 32)"\njava -Xmx512m -jar \\\n  sync-app/target/rivomesh-app-0.1.0-SNAPSHOT.jar \\\n  serve config/platform.yml'))
async function copy(){try{await navigator.clipboard.writeText(command.value);copied.value=true;copyError.value=false;clearTimeout(timer);timer=setTimeout(()=>copied.value=false,2000)}catch{copyError.value=true}}
onBeforeUnmount(()=>clearTimeout(timer))
</script>
<template><div class="quick-start-code"><div class="command-toolbar"><div role="group" :aria-label="en?'Choose deployment method':'选择部署方式'"><button :aria-pressed="method==='docker'" :class="{selected:method==='docker'}" @click="method='docker'">Docker Compose</button><button :aria-pressed="method==='java'" :class="{selected:method==='java'}" @click="method='java'">Java 21 + Maven</button></div><button class="copy-command" @click="copy">{{copied?(en?'Copied':'已复制'):(en?'Copy':'复制命令')}}</button></div><pre tabindex="0" :aria-label="en?'Installation commands':'安装命令'"><code>{{command}}</code></pre><p aria-live="polite" class="command-note">{{copyError?(en?'Copy is unavailable. Select the commands manually.':'暂时无法复制，请手动选择命令。'):(method==='docker'?(en?'Requires Git, Docker Compose and openssl. Builds a local image from source.':'需要 Git、Docker Compose 与 openssl，从源码构建本地镜像。'):(en?'Requires Git, Eclipse Temurin 21 LTS, Maven and openssl.':'需要 Git、Eclipse Temurin 21 LTS、Maven 与 openssl。'))}}</p></div></template>
<style scoped>
.quick-start-code{min-width:0;border:1px solid var(--line);border-radius:8px;overflow:hidden;background:var(--canvas)}.command-toolbar{display:flex;justify-content:space-between;align-items:center;gap:14px;border-bottom:1px solid var(--line);padding:9px 12px;background:var(--surface)}.command-toolbar>div{display:flex;gap:3px}.command-toolbar button{font-size:11px;padding:8px 10px;border-radius:4px;color:var(--muted)}.command-toolbar button.selected{background:var(--canvas);color:var(--ink);box-shadow:0 1px 3px #0001}.command-toolbar .copy-command{color:var(--blue);white-space:nowrap;border:1px solid var(--line)}.quick-start-code pre{font-size:12px;line-height:2;padding:23px;overflow-x:auto;white-space:pre;color:var(--ink);margin:0}.command-note{font-size:10px;color:var(--muted);border-top:1px solid var(--line);padding:12px 18px;line-height:1.8;margin:0}@media(max-width:600px){.command-toolbar{gap:6px;padding:8px}.command-toolbar button{font-size:10px;padding:7px}.quick-start-code pre{font-size:10px;padding:18px}.command-note{font-size:10px}}
</style>
